import {useEffect,useRef,useState,lazy,Suspense,type ReactNode} from 'react';
import {Cpu,ArrowRight,Search,BookOpen,Network,FileDown,CheckCircle2,AlertTriangle,Plus,Trash2,Save,MessageSquare,ClipboardList,FlaskConical,LoaderCircle,ChevronRight,Settings2} from 'lucide-react';
