const MotionFeedback=lazy(()=>import('./components/MessageFeedback'));
function ReplyFeedback({active,children}:{active:boolean;children:ReactNode}){return active?<Suspense fallback={<>{children}</>}><MotionFeedback>{children}</MotionFeedback></Suspense>:<>{children}</>;}
import './hardware.css';
