type Fact={value:unknown;unit:string;source_url:string;status:string;scope?:string};
type Part={id:string;name:string;mpn:string;manufacturer:string;category:string;kind:string;source_url:string;facts:Record<string,Fact>;notes:string[]};
type CustomPart={id:string;name:string;category:string;kind:string;manufacturer:string;source_url:string;facts:Record<string,{value:unknown;unit:string}>;notes:string};
type Bom={ref:string;part_id:string;quantity:number;unit_price_cny:number|null;quote_source?:string;quote_at?:string|null;quote_kind?:string;notes?:string};
type Edge={from_ref:string;to_ref:string;kind:string;protocol?:string;voltage_v?:number|null;load_a?:number|null;notes?:string};
export type Project={conversation_id?:string|null;name:string;description:string;domain:string;requirements:Record<string,string>;budget_cny:number|null;bom:Bom[];connections:Edge[];custom_parts:CustomPart[]};
export type ChatMessage={role:string;text:string;reason?:string;question_key?:string|null;choices?:string[]};
type SearchRecord={status:string;mode:string;request_count:number;request_ids:string[];results:{id:string;title:string;url:string;snippet:string;product_url?:string|null;platform?:string}[];error:string|null};
type DiscoveredPart={name:string;source_id:string;source_url:string;product_url?:string|null;platform?:string;role:string;reason:string;status:string};
export type DecisionTrace={id:string;new_model_requests:number;new_search_requests:number;change_reason:string;model_calls:{model:string;request_id:string}[];search?:SearchRecord|null;prior_evidence_count?:number;assumptions?:string[]};
type CheckItem={id:string;name:string;status:string;reason:string;from_ref:string;to_ref:string;evidence:{part_id:string;field:string;source_url?:string;status:string}[]};
type Review={project:Project;review_id:string;created_at:string;verdict:string;checks:CheckItem[];budget:{known_subtotal_cny:number;total_cny:number|null;missing_price_lines:number;status:string;scope:string};clarifications:string[];verification_actions:{priority:string;title:string;reason:string;affected_refs:string[];steps:string[];pass_condition:string;executed:boolean}[];change_impact:{ref:string;field:string;before:unknown;after:unknown;affected_checks:string[];effect:string}[];architecture:{draft_function_blocks:string[]};search:SearchRecord;limitations:string[]};
type Doc={id:string;name:string;page_count:number;status:string};
type PriceLead={title:string;source_url:string;snippet:string;amount_cny:number|null;price_candidates_cny:number[];quote_type:string;reason:string;retrieved_at:string;currency?:string;product_url?:string|null;platform?:string;model_match_scope?:string};
const blank:Project={name:'未命名硬件项目',description:'',domain:'auto',requirements:{},budget_cny:null,bom:[],connections:[],custom_parts:[]};
const labels:Record<string,string>={controller:'主控',sensor:'传感器',power:'电源',vision:'视觉',compute:'计算',custom:'自定义',unconfirmed:'形态待确认',ic:'芯片',module:'模块',board:'开发板',power_io:'输入/输出与负载',power_source:'供电',connectivity:'通信',budget:'预算',resources:'资源与经验',tracking_method:'循迹方式',performance:'性能目标',project_type:'目标项目',sensing_tech:'感知路线',battery:'电池条件',existing_controller:'已有主控与工具',programming_language:'编程基础',motor_config:'电机与运动',retain_route:'保留方案',scenario:'使用场景',experience:'开发经验',soldering:'焊接条件',timeline:'时间安排',floor_type:'地面条件',track:'路线条件',existing_hardware:'已有器材',soldering_preference:'焊接偏好',goal:'目标效果',deadline:'完成时间',purpose:'目标功能',load:'负载',pass:'已覆盖',fail:'存在冲突',unknown:'待核验',not_requested:'未设置',supply_min_v:'最低供电',supply_max_v:'最高供电',output_voltage_v:'输出电压',logic_voltage_v:'输出电平',io_input_max_v:'输入耐受',interfaces:'接口',clock_mhz:'主频',digital_pins:'数字引脚',analog_inputs:'模拟输入',io_supply_min_v:'I/O供电下限',io_supply_max_v:'I/O供电上限'};
const show=(v:unknown)=>v===null||v===undefined?'未知':Array.isArray(v)?v.join(' / '):String(v);
const safe=(url:string)=>{try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?url:undefined;}catch{return undefined;}};
const number=(v:string)=>v===''?null:Number(v);
const readChat=(id:string|null|undefined)=>{try{return id?JSON.parse(localStorage.getItem('racechip-chat-'+id)||'null'):null;}catch{return null;}};
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value)) as T;
const stamp=()=>new Date().toISOString();
function Source({url,label}:{url:string;label?:string}){const href=safe(url);if(!href)return <span className="hw-muted">来源待录入</span>;return <a href={href} target="_blank" rel="noopener noreferrer">{label||new URL(href).hostname} ↗</a>;}
function Tag({status}:{status:string}){return <span className={'hw-tag '+status}>{labels[status]||status}</span>;}
function SearchProof({value}:{value:SearchRecord|null}){return value?<div className="hw-proof"><strong>元宝搜索 · {value.mode==='live'?'真实联网':value.mode==='mock'?'MOCK测试':'未检索'}</strong><span>{value.status} · {value.request_count} 次请求</span>{value.error&&<p role="alert">{value.error}</p>}{value.request_ids?.length>0&&<details><summary>服务端查询凭据</summary>{value.request_ids.map(id=><code key={id}>{id}</code>)}</details>}</div>:null;}

function Architecture({project,parts}:{project:Project;parts:Part[]}){
  if(!project.bom.length)return <div className="hw-design-empty">这里会根据采用后的具体器件与功能关系生成系统草案。先在上方点击“生成方案并搜索配件”，再采用清单到BOM。</div>;
  const width=850,height=Math.max(160,Math.ceil(project.bom.length/3)*115);
  const pos=(ref:string)=>{const i=project.bom.findIndex(b=>b.ref===ref);return {x:20+(i%3)*280,y:20+Math.floor(i/3)*115};};
  return <div className="hw-architecture"><svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label="可编辑系统架构草案"><defs><marker id="hw-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#8d9b88"/></marker></defs>{project.connections.map((e,i)=>{const a=pos(e.from_ref),b=pos(e.to_ref);return <g key={i}><path d={`M${a.x+120},${a.y+64} L${b.x+120},${b.y+64}`} stroke={e.kind==='power'?'#c66b3e':'#8d9b88'} strokeWidth="1.6" markerEnd="url(#hw-arrow)"/><text x={(a.x+b.x)/2+120} y={(a.y+b.y)/2+88} textAnchor="middle" fill="#65715f" fontSize="10">{e.protocol||({power:'供电',signal:'信号',protocol:'协议',mechanical:'机械',software:'软件'} as Record<string,string>)[e.kind]}</text></g>;})}{project.bom.map(b=>{const p=parts.find(p=>p.id===b.part_id),xy=pos(b.ref);return <g key={b.ref} transform={`translate(${xy.x},${xy.y})`}><title>{b.ref} · {p?.name||b.part_id}</title><rect width="240" height="64" rx="6" fill="#fffef7" stroke="#cbd3c3"/><text x="14" y="22" fill="#78856f" fontSize="10">{b.ref} · {labels[p?.category||'custom']||p?.category}</text><text x="14" y="44" fill="#244936" fontSize="13" fontWeight="600">{(p?.name||b.part_id).slice(0,25)}</text></g>;})}</svg><small>系统级连接草案，尚非原生EDA原理图。按上方BOM与下方连接编辑。</small></div>;
}

export default function HardwareWorkspace(){
  const [tab,setTab]=useState('guide');const [showDemo,setShowDemo]=useState(false);
  const [project,setProject]=useState<Project>(()=>{try{const value=JSON.parse(localStorage.getItem('racechip-project-v3')||'null')||clone(blank);return {...value,conversation_id:value.conversation_id||crypto.randomUUID()};}catch{return {...clone(blank),conversation_id:crypto.randomUUID()};}});
  const [catalog,setCatalog]=useState<Part[]>([]);const [domains,setDomains]=useState<Record<string,string>>({});
  const [health,setHealth]=useState<{search_configured:boolean;version:string;decision?:DecisionStatus}|null>(null);
  const [examples,setExamples]=useState<{id:string;title:string;description:string;project:Project}[]>([]);
  const [modelPanel,setModelPanel]=useState(false);const [decisionTrace,setDecisionTrace]=useState<DecisionTrace|null>(()=>readChat(project.conversation_id)?.decisionTrace||null);const chatLog=useRef<HTMLDivElement>(null);
  const [buildPlan,setBuildPlan]=useState<BuildPlan|null>(()=>readChat(project.conversation_id)?.buildPlan||null);
  const [discoveredParts,setDiscoveredParts]=useState<DiscoveredPart[]>(()=>readChat(project.conversation_id)?.discoveredParts||[]);
  const [neededModules,setNeededModules]=useState<string[]>(()=>readChat(project.conversation_id)?.neededModules||[]);const [candidateIds,setCandidateIds]=useState<string[]>(()=>readChat(project.conversation_id)?.candidateIds||[]);const [messages,setMessages]=useState<ChatMessage[]>(()=>readChat(project.conversation_id)?.messages||[]);const [pending,setPending]=useState<string|null>(()=>readChat(project.conversation_id)?.pending||null);const [chat,setChat]=useState(()=>readChat(project.conversation_id)?.draft||'');
  const [busy,setBusy]=useState('');const [error,setError]=useState('');const [notice,setNotice]=useState('');
  const [review,setReview]=useState<Review|null>(null);const [previous,setPrevious]=useState<Project|null>(null);
  const [query,setQuery]=useState('');const [mode,setMode]=useState('mock');const [search,setSearch]=useState<SearchRecord|null>(null);
  const [category,setCategory]=useState('');const [hits,setHits]=useState<SearchRecord['results']>([]);
  const [partResult,setPartResult]=useState<DiscoveryResponse|null>(null);const [partBusy,setPartBusy]=useState(false);const [partError,setPartError]=useState('');const [partSubmitted,setPartSubmitted]=useState('');const partAbort=useRef<AbortController|null>(null);
  const normalizePart=(value:string)=>value.toLowerCase().replace(/[^\p{L}\p{N}]/gu,'');
  function hasDiscovered(name:string){return project.bom.some(b=>allParts.some(p=>p.id===b.part_id&&(normalizePart(p.name)===normalizePart(name)||normalizePart(p.mpn)===normalizePart(name))));}
  function addDiscovered(part:DiscoveredCandidate){if(hasDiscovered(part.name))return;const existing=allParts.find(p=>normalizePart(p.name)===normalizePart(part.name)||normalizePart(p.mpn)===normalizePart(part.name));if(existing){addPart(existing);return;}const id='found-'+crypto.randomUUID().slice(0,12);let i=1;while(project.bom.some(b=>b.ref==='U'+i))i++;setProject({...project,custom_parts:[...project.custom_parts,{id,name:part.name,category:part.category||'custom',kind:'unconfirmed',manufacturer:'厂商与版本待核对',source_url:part.source_url,facts:{},notes:'从元宝实际来源匹配到的型号文字；形态、参数、SKU和供货尚未核实。'}],bom:[...project.bom,{ref:'U'+i,part_id:id,quantity:1,unit_price_cny:null,quote_kind:'unknown',quote_source:part.source_url}]});setNotice(part.name+' 已加入BOM，参数和形态保留待核验。');}
  function revealPrices(){requestAnimationFrame(()=>{document.getElementById('price-query')?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});document.getElementById('price-query')?.focus({preventScroll:true});});}

  const [priceError,setPriceError]=useState('');const [priceModel,setPriceModel]=useState('');const [priceType,setPriceType]=useState('模块');const [prices,setPrices]=useState<PriceLead[]>([]);const [targetRef,setTargetRef]=useState('');
  const [comparisonIds,setComparisonIds]=useState<string[]>([]);const [comparison,setComparison]=useState<{rows:{field:string;values:Fact[];different:boolean}[];parts:Part[];note:string}|null>(null);
  const [edge,setEdge]=useState<Edge>({from_ref:'',to_ref:'',kind:'protocol',protocol:'I2C',voltage_v:null,load_a:null,notes:''});
  const [custom,setCustom]=useState({name:'',category:'custom',kind:'module',source_url:'',key:'supply_max_v',value:'',unit:'V'});
  const [docs,setDocs]=useState<Doc[]>([]);const [docIds,setDocIds]=useState<string[]>([]);const [docName,setDocName]=useState('');const [docText,setDocText]=useState('');const [docUrl,setDocUrl]=useState('');
  const [question,setQuestion]=useState('');const [answer,setAnswer]=useState<{answer:string;citations:{text:string;document:string;page:number|null;source_url:string}[];scope:string}|null>(null);
  const composer=useRef<HTMLTextAreaElement>(null);
  function chooseStarter(value:string){setChat(value);requestAnimationFrame(()=>{composer.current?.focus({preventScroll:true});if(matchMedia('(max-width:700px)').matches)composer.current?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});});}
  const activeRequest=useRef<AbortController|null>(null);const [saved,setSaved]=useState<{id:string;name:string}[]>([]);const fileInput=useRef<HTMLInputElement>(null);
  const customParts:Part[]=project.custom_parts.map(p=>({...p,manufacturer:p.manufacturer||'用户录入',mpn:p.name,notes:[p.notes||'用户录入参数，未核验。'],facts:Object.fromEntries(Object.entries(p.facts||{}).map(([k,v])=>[k,{...v,source_url:p.source_url,status:'user_asserted'}]))}));
  const allParts=[...catalog,...customParts];
  const localParts=allParts.filter(p=>(!category||p.category===category)&&(!query||normalizePart(`${p.name} ${p.mpn}`).includes(normalizePart(query))));
  const dirty=!!review&&JSON.stringify(review.project)!==JSON.stringify(project);
  useEffect(()=>{try{localStorage.setItem('racechip-project-v3',JSON.stringify(project));}catch{/* Browser storage may be unavailable; explicit server save remains available. */}},[project]);
  useEffect(()=>{if(!project.conversation_id)return;try{localStorage.setItem('racechip-chat-'+project.conversation_id,JSON.stringify({messages,pending,neededModules,candidateIds,decisionTrace,discoveredParts,buildPlan,draft:chat.replace(/AKID[A-Za-z0-9]{20,}|sk-[A-Za-z0-9_-]{20,}/g,'[密钥已过滤]')}));}catch{}},[messages,pending,neededModules,candidateIds,decisionTrace,discoveredParts,buildPlan,chat,project.conversation_id]);
  useEffect(()=>{if(chatLog.current)chatLog.current.scrollTop=chatLog.current.scrollHeight;},[messages,busy]);
  useEffect(()=>{Promise.allSettled([fetch('/api/health').then(r=>r.json()),fetch('/api/hardware/catalog').then(r=>r.json()),fetch('/api/hardware/examples').then(r=>r.json()),fetch('/api/hardware/documents').then(r=>r.json()),fetch('/api/hardware/projects').then(r=>r.json())]).then(([h,c,e,d,s])=>{if(h.status==='fulfilled'){setHealth(h.value);if(h.value.search_configured)setMode('live');}if(c.status==='fulfilled'&&c.value.parts){setCatalog(c.value.parts);setDomains(c.value.domains);}if(e.status==='fulfilled'&&Array.isArray(e.value))setExamples(e.value);if(d.status==='fulfilled'&&Array.isArray(d.value))setDocs(d.value);if(s.status==='fulfilled'&&Array.isArray(s.value))setSaved(s.value);});},[]);
  async function api(path:string,body:unknown){const controller=new AbortController();activeRequest.current=controller;const timeout=setTimeout(()=>controller.abort(),300000);try{const response=await fetch('/api/hardware/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:controller.signal});const data=await response.json().catch(()=>null);if(!response.ok)throw new Error(typeof data?.detail==='string'?data.detail:typeof data?.detail?.message==='string'?data.detail.message+(data.detail.code?`（${data.detail.code}）`:''):`请求未完成（HTTP ${response.status}），请检查输入条件。`);return data;}catch(cause){if(cause instanceof Error&&cause.name==='AbortError')throw new Error('请求已取消或超过300秒。输入已保留；已发送的上游请求不保证撤销。');throw cause;}finally{clearTimeout(timeout);activeRequest.current=null;}}
  async function task(name:string,work:()=>Promise<void>){setBusy(name);setError('');setNotice('');try{await work();}catch(e){setError(e instanceof Error?e.message:'操作未完成');}finally{setBusy('');}}
  function addPart(part:Part){let i=1;while(project.bom.some(b=>b.ref==='U'+i))i++;setProject({...project,bom:[...project.bom,{ref:'U'+i,part_id:part.id,quantity:1,unit_price_cny:null,quote_kind:'unknown'}]});setNotice(`${part.name} 已加入BOM，尚未核验完整连接。`);}
  function updateLine(index:number,patch:Partial<Bom>){setProject({...project,bom:project.bom.map((b,i)=>i===index?{...b,...patch}:b)});}
  function removeLine(ref:string){setProject({...project,bom:project.bom.filter(b=>b.ref!==ref),connections:project.connections.filter(e=>e.from_ref!==ref&&e.to_ref!==ref)});}
  async function refreshHealth(){const response=await fetch('/api/health');if(response.ok)setHealth(await response.json());}
  async function send(text=chat){if(!text.trim()||busy)return;if(/AKID[A-Za-z0-9]{20,}|sk-[A-Za-z0-9_-]{20,}/.test(text)){setError('消息看起来包含密钥，请使用模型配置入口，不要将密钥发送到对话。');return;}if(!health?.decision?.configured){setModelPanel(true);setError('上下文决策需要TokenHub专用Key；请先完成本机配置。器件、报价和BOM工具可独立使用。');return;}await task('模型正在结合上下文决策，必要时调用元宝补查',async()=>{const data=await api('dialogue',{project,message:text,pending_key:pending,history:messages});setProject(data.project);setDecisionTrace(data.decision_trace||null);setDiscoveredParts(data.discovered_parts||[]);setBuildPlan(data.build_plan||null);setMessages(data.history);setPending(data.assistant.question_key);setNeededModules(data.needed_modules||[]);setCandidateIds((data.candidate_parts||[]).map((p:{part_id:string})=>p.part_id));setChat('');});await refreshHealth();}
  async function inspect(online=false){await task(online?'元宝搜索与方案核验中':'正在核算方案',async()=>{const data=await api('review',{project,previous_project:previous,search_mode:online?mode:'off'});setReview(data);setProject(data.project);setPrevious(clone(data.project));});}
  async function searchParts(){if(partBusy||query.trim().length<2)return;setPartBusy(true);setPartError('');setPartResult(null);setPartSubmitted(query.trim());const controller=new AbortController();partAbort.current=controller;const timeout=setTimeout(()=>controller.abort(),90000);try{const response=await fetch('/api/hardware/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:query.trim(),category,mode}),signal:controller.signal});const data=await response.json();if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'器件搜索未完成');setPartResult(data);}catch(cause){setPartError(cause instanceof Error&&cause.name==='AbortError'?'器件搜索超过90秒或已取消，可保留当前查询重试。':cause instanceof Error?cause.message:'器件搜索未完成，请检查服务连接。');}finally{clearTimeout(timeout);partAbort.current=null;setPartBusy(false);}}
  async function searchPrices(model=priceModel,itemType=priceType){setPriceError('');setPrices([]);setHits([]);setSearch(null);await task('元宝正在检索商家报价',async()=>{try{const data=await api('prices',{mpn:model,item_type:itemType,mode});setSearch(data.search);setPrices(data.price_leads);if(!data.price_leads.length)setNotice('没有可用价格线索；不会填入虚构价格。可打开返回来源，核对后手动录入。');setHits(data.search.results);}catch(cause){setPriceError(cause instanceof Error?cause.message:'报价搜索未完成。');throw cause;}});}
  function applyPrice(lead:PriceLead){const i=project.bom.findIndex(b=>b.ref===targetRef);if(i<0||lead.amount_cny===null){setError('请先选目标BOM行；只有单一明确人民币价格线索可预填。');return;}updateLine(i,{unit_price_cny:lead.amount_cny,quote_source:lead.source_url,quote_at:lead.retrieved_at,quote_kind:'search_lead'});setNotice('已填入参考价，仍待人工核对SKU、套装与数量；预算不会自动判为已确认。');}
  async function exportProject(){await task('生成工程交接包',async()=>{const response=await fetch('/api/hardware/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project,previous_project:previous,review_id:review?.review_id})});if(!response.ok)throw new Error('导出失败，请先检查方案输入。');const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download='RaceChip-hardware-handoff.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);});}
  async function importCsv(file:File){await task('导入BOM',async()=>{const data=await api('import-bom',{csv_text:await file.text()});setProject({...project,bom:data.bom,custom_parts:[...project.custom_parts,...data.custom_parts],connections:[]});setNotice(`导入${data.bom.length}行；${data.errors.length}行需修正。${data.errors.map((e:{row:number;reason:string})=>`第${e.row}行：${e.reason}`).join('；')}`);});}
  async function save(){await task('保存本机项目',async()=>{const data=await api('projects',project);setSaved([...saved,data]);setNotice('项目已保存到本机，未上传云端。');});}
  async function load(id:string){await task('载入项目',async()=>{const response=await fetch('/api/hardware/projects/'+id);if(!response.ok)throw new Error('项目载入失败');const value=await response.json() as Project;value.conversation_id=value.conversation_id||crypto.randomUUID();setProject(value);setReview(null);setPrevious(null);let state=readChat(value.conversation_id);const history=await fetch('/api/hardware/conversations/'+value.conversation_id);if(history.ok){const remote=await history.json();state={messages:remote.history,pending:remote.assistant?.question_key,neededModules:remote.needed_modules,candidateIds:remote.candidate_parts?.map((p:{part_id:string})=>p.part_id),decisionTrace:remote.decision_trace,discoveredParts:remote.discovered_parts,buildPlan:remote.build_plan};}setMessages(state?.messages||[]);setPending(state?.pending||null);setNeededModules(state?.neededModules||[]);setCandidateIds(state?.candidateIds||[]);setDecisionTrace(state?.decisionTrace||null);setDiscoveredParts(state?.discoveredParts||[]);setBuildPlan(state?.buildPlan||null);setChat(state?.draft||'');});}
  async function addDocument(){await task('保存本机资料',async()=>{const d=await api('documents',{name:docName||'用户资料',text:docText,source_url:docUrl});setDocs([...docs,d]);setDocIds([...docIds,d.id]);setDocText('');setNotice('资料已在本机保存；来源真伪和版本仍需核对。');});}
  async function addPdf(file:File){await task('提取PDF文本',async()=>{const r=await fetch('/api/hardware/documents/pdf?name='+encodeURIComponent(file.name),{method:'POST',headers:{'Content-Type':'application/pdf'},body:await file.arrayBuffer()});const data=await r.json();if(!r.ok)throw new Error(data.detail||'PDF读取失败');setDocs([...docs,data]);setDocIds([...docIds,data.id]);setNotice(`已提取${data.page_count}页文本；扫描图片和图表不能据此自动判读。`);});}
  async function ask(){await task('按原文定位答案',async()=>{const data=await api('qa',{question,document_ids:docIds,part_ids:project.bom.map(b=>b.part_id)});setAnswer(data);});}
  function addCustom(){if(!custom.name.trim())return;const existing=project.custom_parts.find(p=>p.name.trim().toLowerCase()===custom.name.trim().toLowerCase());const id=existing?.id||'user-'+crypto.randomUUID().slice(0,8);const p:CustomPart={id,name:custom.name,manufacturer:'用户录入',category:custom.category,kind:custom.kind,source_url:custom.source_url,facts:{...(existing?.facts||{}),...(custom.value!==''?{[custom.key]:{value:custom.key==='interfaces'?custom.value.split(/[,，、]/).map(v=>v.trim().toUpperCase()):Number.isFinite(Number(custom.value))?Number(custom.value):custom.value,unit:custom.unit}}:{})},notes:'用户录入参数，未自动核对原文。'};setProject({...project,custom_parts:existing?project.custom_parts.map(item=>item.id===id?p:item):[...project.custom_parts,p]});setCustom({...custom,name:'',value:''});setNotice('已新增自定义型号；用户参数不会自动成为已核验证据。');}

  return <div className="hardware-app">
    <header className="hw-header"><a className="hw-brand" href="#" onClick={e=>{e.preventDefault();setTab('guide');}}><span><Cpu size={24}/></span><div><strong>赛芯智选 <small>RaceChip AI</small></strong><p>让每个硬件想法，有路可走</p></div></a><div className="hw-connection"><i className={health?.search_configured?'connected':''}/>{health?.search_configured?'元宝搜索已连接':'离线资料模式'}<small>v{health?.version||'0.3'}</small></div><div className="hw-header-actions"><button className="hw-button hw-model-toggle" aria-label="模型配置" disabled={!!busy} onClick={()=>setModelPanel(v=>!v)}><Settings2 size={15}/><span className="hw-action-label">模型配置</span></button><button className="hw-button" aria-label="新建" disabled={!!busy} onClick={()=>{setProject({...clone(blank),conversation_id:crypto.randomUUID()});setDecisionTrace(null);setDiscoveredParts([]);setBuildPlan(null);setShowDemo(false);setChat('');setMessages([]);setPending(null);setCandidateIds([]);setNeededModules([]);setReview(null);setPrevious(null);setNotice("已新建空白项目；已保存项目可从打开菜单恢复。");}}><Plus size={15}/><span className="hw-action-label">新建</span></button><button className="hw-button" aria-label="保存项目" disabled={!!busy} onClick={save}><Save size={15}/><span className="hw-action-label">保存项目</span></button>{saved.length>0&&<select aria-label="打开已保存项目" value="" onChange={e=>e.target.value&&load(e.target.value)}><option value="">打开</option>{saved.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select>}</div></header>
    <div className="hw-layout"><aside className="hw-sidebar"><div className="hw-sidebar-label">工作流</div>{[{id:'guide',label:'需求对话',icon:MessageSquare},{id:'design',label:'方案与BOM',icon:Network},{id:'parts',label:'器件与报价',icon:Search},{id:'documents',label:'资料问答',icon:BookOpen},{id:'audit',label:'证据核验',icon:FlaskConical}].map(n=><button key={n.id} className={tab===n.id?'selected':''} aria-current={tab===n.id?'page':undefined} disabled={!!busy} onClick={()=>{setTab(n.id);setShowDemo(false);}}><n.icon size={17}/>{n.label}<ChevronRight size={13}/></button>)}<div className="hw-sidebar-project"><span>当前项目</span><strong>{project.name}</strong><small>{domains[project.domain]||'待定位方向'}</small><p>{project.bom.length}项BOM · {project.connections.length}条连接</p>{saved.length>0&&<label>打开本机项目<select value="" onChange={e=>e.target.value&&load(e.target.value)}><option value="">选择已保存项目</option>{saved.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label>}</div><div className="hw-sidebar-foot">联网内容统一经元宝搜索。<br/>原文、价格与未知项可追溯。</div></aside>
    <main className="hw-main">
      {showDemo&&<NoviceDemo onClose={()=>setShowDemo(false)}/>} {modelPanel&&<ModelConnection status={health?.decision} onChange={refreshHealth} onClose={()=>setModelPanel(false)}/>}{error&&<div className="hw-alert error" role="alert"><AlertTriangle size={17}/>{error}</div>}{notice&&<div className="hw-alert" role="status">{notice}</div>}{busy&&<div className="hw-busy" role="status"><LoaderCircle size={16} className="spin"/>{busy}{activeRequest.current&&<button type="button" className="hw-cancel" onClick={()=>activeRequest.current?.abort()}>取消本次请求</button>}</div>}
      <fieldset className="hw-work-area" disabled={!!busy} hidden={showDemo}>{tab==='guide'&&<><div className="hw-page-title hw-guide-title"><h1>把你的想法，<span>做成硬件。</span></h1><p>从一句“我想做……”开始，一起找到合适的方案、配件和下一步。</p></div><ProjectJourney started={messages.length>0} planned={!!buildPlan||project.bom.length>0} onGuide={()=>composer.current?.focus()} onDesign={()=>setTab('design')}/><div className="hw-model-state"><span className={health?.decision?.status==="available"?"ready":"pending"}/><strong>{health?.decision?.status==="available"?"上下文模型已验证":health?.decision?.configured?"模型已配置，尚待验证":"上下文模型待连接"}</strong><span>搜索：元宝 SearchPro</span><button type="button" className="hw-quick-demo" onClick={()=>setShowDemo(true)}>先看完整示例</button><button type="button" onClick={()=>setModelPanel(true)}>配置与状态</button></div><div className="hw-guide-grid"><section className="hw-chat-card"><div className="hw-card-heading"><MessageSquare size={18}/><h2>需求定位</h2><span>一步一步来</span></div>{messages.length===0?<div className="hw-chat-empty"><h3>{project.description?'继续完善当前方案':'今天，想做点什么？'}</h3><p>{project.description?`当前目标：${project.description}`:'选一个方向试试，或者在下方写下你自己的想法。'}</p>{!project.description&&<ProjectStarters draft={chat} onChoose={chooseStarter}/>}</div>:<div className="hw-messages" ref={chatLog} aria-live="polite">{messages.map((m,i)=><ReplyFeedback key={i} active={m.role==='assistant'&&i===messages.length-1}><article key={i} className={m.role}><span>{m.role==='user'?'你':'赛芯智选'}</span><p>{m.text}</p>{m.reason&&<small>{m.reason}</small>}{i===messages.length-1&&m.choices&&<div className="hw-quick-answers">{m.choices.map(c=><button key={c} disabled={!!busy} onClick={()=>send(c)}>{c}</button>)}</div>}</article></ReplyFeedback>)}</div>}{decisionTrace&&<details className="hw-decision-trace"><summary>本轮决策依据 · 模型{decisionTrace.new_model_requests}次 / 元宝{decisionTrace.new_search_requests}次</summary><p>{decisionTrace.change_reason||"模型依据本轮上下文返回的下一步。"}</p>{decisionTrace.model_calls.map((c,i)=><p key={i}>{c.model}<code>{c.request_id||"供应商未返回RequestId"}</code></p>)}<SearchProof value={decisionTrace.search||null}/>{decisionTrace.search?.results?.slice(0,6).map(hit=><p key={hit.id}><Source url={hit.url} label={hit.title}/></p>)}{decisionTrace.assumptions?.length?<p>待确认：{decisionTrace.assumptions.join("；")}</p>:null}</details>}<form className="hw-chat-input" onSubmit={e=>{e.preventDefault();send();}}><label className="hw-composer-label" htmlFor="hw-message">{pending?'回答当前问题':'描述硬件目标'}</label><textarea ref={composer} id="hw-message" value={chat} onChange={e=>setChat(e.target.value)} rows={3} placeholder={pending?'回答这一个问题，也可以补充条件……':'例如：我想做一个低功耗无线温湿度采集节点……'}/><div><span className={chat.trim()?'hw-composer-ready':undefined}>{pending?'回答当前问题，也可以补充新的条件':chat.trim()?'想法已就位，可以继续修改后开始':'只需一句话，细节我们一步步确认'}</span><button className="hw-primary" disabled={!!busy||!chat.trim()}>{health?.decision?.configured?(messages.length?'继续定位':'开始我的方案'):'连接模型，开始方案'}<ArrowRight size={15}/></button></div></form></section><div className="hw-guide-aside">{messages.length===0&&<ExamplePreview onPlay={()=>setShowDemo(true)}/>}<aside className="hw-confirmed" hidden={!messages.length&&!project.description&&!Object.keys(project.requirements).length}><h2>逐步确认的条件</h2><div className="hw-domain">{domains[project.domain]||'等待定位方向'}</div>{Object.keys(project.requirements).length?Object.entries(project.requirements).map(([k,v])=><div className="hw-requirement" key={k}><span>{labels[k]||k}</span><strong>{v}</strong></div>):<p>回答后，这里会记录已确认的条件；尚未说明的参数保持未知。</p>}{project.budget_cny!==null&&!project.requirements.budget&&<div className="hw-requirement"><span>所填预算</span><strong>¥{project.budget_cny}</strong></div>}{neededModules.length>0&&<div className="hw-candidates"><h3>需要逐步选型的模块</h3><p>功能拆分草案，型号与连接尚待核验。</p>{neededModules.map(name=><button key={name} onClick={()=>{setQuery(name+' '+project.description.slice(0,100));setTab('parts');}}>{name}<Search size={13}/></button>)}</div>}{candidateIds.length>0&&<div className="hw-candidates"><h3>有出处的初步候选</h3><p>仅是比较起点，尚未通过当前项目核验。</p>{candidateIds.map(id=>{const part=catalog.find(p=>p.id===id);return part?<button key={id} onClick={()=>addPart(part)}>{part.name}<Plus size={13}/></button>:null;})}</div>}{discoveredParts.length>0&&<div className="hw-discovered"><h3>元宝发现的型号线索</h3><p>尚未核验规格；打开原始来源后可录入方案。</p>{discoveredParts.map((p,i)=><article key={p.source_id+String(i)}><strong>{p.name}</strong><small>{p.role}</small><p>{p.reason}</p><Source url={p.product_url||p.source_url} label={p.product_url?`打开${p.platform||"平台"}商品详情`:"查看型号来源"}/><button type="button" className="hw-button" onClick={()=>{setCustom({...custom,name:p.name,source_url:p.source_url,value:""});setQuery(p.name);setTab("parts");}}>录入此型号</button></article>)}</div>}<button className="hw-button" onClick={()=>{setQuery(project.description.slice(0,350));setTab('parts');}}>用元宝继续发现型号</button><button className="hw-primary" onClick={()=>setTab('design')}>进入可编辑方案<ArrowRight size={15}/></button><small>可带着未知项进入草案，后续围绕具体冲突继续确认。</small></aside>{!messages.length&&<section className="hw-output-promise"><h2>从想法出发，你会得到</h2><p><CheckCircle2 size={14}/>适合当前目标的硬件路线</p><p><CheckCircle2 size={14}/>规格、数量与配套条件清单</p><p><CheckCircle2 size={14}/>可编辑的 BOM 与工程交接包</p><small>商品链接需联网检索；具体 SKU、价格与兼容条件保留核对项。</small></section>}</div></div>{buildPlan&&decisionTrace&&project.conversation_id&&<GuidedPlan plan={buildPlan} conversationId={project.conversation_id} decisionId={decisionTrace.id} ready={!pending} onApply={async id=>{const data=await api("procurement/"+id+"/apply",{project});setProject(data.project);setReview(null);setNotice(data.notice);setTab("design");}}/>}</>}
      {tab==='design'&&<><div className="hw-section-title"><div><h1>方案、连接与完整BOM</h1><p>填写目标，生成方案并查找配件；采用清单后，继续编辑BOM、报价和连接。</p></div><button className="hw-button" disabled={!!busy} onClick={exportProject}><FileDown size={16}/>导出工程交接包</button></div><div className="hw-project-form"><label>项目名<input aria-label="项目名" value={project.name} onChange={e=>setProject({...project,name:e.target.value})}/></label><label>方向<select aria-label="项目方向" value={project.domain} onChange={e=>setProject({...project,domain:e.target.value})}><option value="auto">自动定位</option>{Object.entries(domains).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>完整预算（元）<input aria-label="完整预算" type="number" min="0" value={project.budget_cny??''} onChange={e=>setProject({...project,budget_cny:number(e.target.value)})}/></label><label>载入自编检查样例<select aria-label="载入自编检查样例" value="" onChange={e=>{const value=examples.find(x=>x.id===e.target.value);if(value){setProject({...clone(value.project),conversation_id:crypto.randomUUID()});setMessages([]);setChat('');setPending(null);setDecisionTrace(null);setDiscoveredParts([]);setBuildPlan(null);setShowDemo(false);setCandidateIds([]);setNeededModules([]);setReview(null);setPrevious(null);setNotice(value.description);}}}><option value="">选择样例</option>{examples.map(x=><option key={x.id} value={x.id}>{x.title}</option>)}</select></label></div><DesignBuilder project={project} ready={!!health?.search_configured&&!!health?.decision?.configured} onConfigure={()=>setModelPanel(true)} onApply={(result,message)=>{setProject(result.project);setBuildPlan(result.build_plan);setDecisionTrace(result.decision_trace);setMessages(result.history);setPending(null);setNeededModules(result.needed_modules||[]);setDiscoveredParts([]);setCandidateIds([]);setReview(null);setPrevious(null);setNotice(message);requestAnimationFrame(()=>document.getElementById('bom-editor')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'}));}}/><section className="hw-card"><div className="hw-card-heading"><Network size={18}/><h2>系统架构草案</h2><span>{project.bom.length?'来自当前器件与连接':'先定位功能，再选型号'}</span></div><Architecture project={project} parts={allParts}/></section>
      <section className="hw-card" id="bom-editor" style={{scrollMarginTop:24}}><div className="hw-card-heading"><ClipboardList size={18}/><h2>BOM与报价</h2><div className="hw-inline-actions"><button onClick={()=>setTab('parts')}><Plus size={14}/>选器件</button><button onClick={()=>fileInput.current?.click()}>导入CSV</button><input ref={fileInput} type="file" accept=".csv,text/csv" hidden onChange={e=>e.target.files?.[0]&&importCsv(e.target.files[0])}/></div></div><p className="hw-small">单价是用户报价或元宝搜索线索；勾选“已核对”只记录你的核对，不代表系统验证商家库存。芯片、模块、套装分开核算。</p><div className="hw-table-scroll"><table className="hw-bom-table"><thead><tr><th>位号 / 型号</th><th>数量</th><th>单价 ¥</th><th>报价来源与确认</th><th/></tr></thead><tbody>{project.bom.map((b,i)=><tr key={b.ref}><td><strong>{b.ref}</strong><select aria-label={`${b.ref}型号`} value={b.part_id} onChange={e=>updateLine(i,{part_id:e.target.value,unit_price_cny:null,quote_source:'',quote_kind:'unknown'})}>{allParts.map(p=><option key={p.id} value={p.id}>{p.name} · {labels[p.kind]||p.kind}</option>)}</select></td><td><input aria-label={`${b.ref}数量`} type="number" min="1" value={b.quantity} onChange={e=>updateLine(i,{quantity:Math.max(1,Number(e.target.value))})}/></td><td><input aria-label={`${b.ref}单价`} type="number" min="0" value={b.unit_price_cny??''} placeholder="未知" onChange={e=>updateLine(i,{unit_price_cny:number(e.target.value),quote_kind:'unknown'})}/></td><td><input aria-label={`${b.ref}报价来源`} value={b.quote_source||''} placeholder="商品SKU链接或人工报价单" onChange={e=>updateLine(i,{quote_source:e.target.value,quote_kind:'unknown'})}/><label className="hw-checkbox"><input type="checkbox" checked={b.quote_kind==='user_quote'} onChange={e=>updateLine(i,{quote_kind:e.target.checked?'user_quote':'unknown',quote_at:stamp()})}/>已核对SKU/套装/数量</label><small>{b.quote_kind==='search_lead'?'搜索线索，仍待核对':b.quote_at?new Date(b.quote_at).toLocaleDateString('zh-CN'):'报价时间未确认'}</small></td><td><button aria-label={`移除${b.ref}`} onClick={()=>removeLine(b.ref)}><Trash2 size={15}/></button></td></tr>)}</tbody></table>{!project.bom.length&&<div className="hw-empty">还没有采用方案或选入器件。可从上方生成并采用清单，也可选器件或导入已有BOM。</div>}</div></section>
      <section className="hw-card"><div className="hw-card-heading"><Network size={18}/><h2>连接与兼容检查</h2></div><div className="hw-edge-form"><label>从<select value={edge.from_ref} onChange={e=>setEdge({...edge,from_ref:e.target.value})}><option value="">选择位号</option>{project.bom.map(b=><option key={b.ref}>{b.ref}</option>)}</select></label><label>到<select value={edge.to_ref} onChange={e=>setEdge({...edge,to_ref:e.target.value})}><option value="">选择位号</option>{project.bom.map(b=><option key={b.ref}>{b.ref}</option>)}</select></label><label>关系<select value={edge.kind} onChange={e=>setEdge({...edge,kind:e.target.value})}><option value="protocol">通信协议</option><option value="power">供电</option><option value="signal">信号电气</option><option value="mechanical">机械装配</option><option value="software">软件/驱动</option></select></label>{edge.kind==='protocol'?<label>协议<input value={edge.protocol||''} onChange={e=>setEdge({...edge,protocol:e.target.value})} placeholder="I2C / CAN / 自定义"/></label>:['power','signal'].includes(edge.kind)?<label>所设计电压 V（可留空）<input type="number" value={edge.voltage_v??''} onChange={e=>setEdge({...edge,voltage_v:number(e.target.value)})}/></label>:<label>版本/条件<input value={edge.notes||''} onChange={e=>setEdge({...edge,notes:e.target.value})}/></label>}<button className="hw-button" onClick={()=>{if(!edge.from_ref||!edge.to_ref||edge.from_ref===edge.to_ref){setError('请选择两个不同的BOM位号');return;}setProject({...project,connections:[...project.connections,clone(edge)]});}}>添加连接</button></div><div className="hw-connections">{project.connections.map((e,i)=><div key={i}><span>{e.from_ref}<ArrowRight size={13}/>{e.to_ref}</span><strong>{e.kind==='power'?'供电':e.kind==='signal'?'信号':e.protocol||e.kind}</strong><small>{e.voltage_v?`${e.voltage_v}V`:'按资料核验'}</small><button aria-label={`移除连接${i+1}`} onClick={()=>setProject({...project,connections:project.connections.filter((_,n)=>n!==i)})}><Trash2 size={14}/></button></div>)}</div><div className="hw-review-actions"><button className="hw-primary" disabled={!!busy} onClick={()=>inspect(false)}>核算当前方案</button><button className="hw-button" disabled={!!busy} onClick={()=>inspect(true)}><Search size={15}/>元宝补查并核验（最多3次）</button><span>{dirty?'输入有变更，需重新核验':review?'结果对应上次输入':'尚未生成检查结果'}</span></div></section>
      {review&&<><section className="hw-review-summary"><Tag status={review.verdict}/><div><span>所填报价小计</span><strong>¥{review.budget.known_subtotal_cny}</strong><small>完整总额 {review.budget.total_cny===null?'未知':`¥${review.budget.total_cny}`} · 缺价{review.budget.missing_price_lines}行</small></div><div><span>连接冲突</span><strong>{review.checks.filter(c=>c.status==='fail').length}</strong></div><div><span>连接待核验</span><strong>{review.checks.filter(c=>c.status==='unknown').length}</strong></div><p>{review.budget.scope}</p></section><SearchProof value={review.search}/><section className="hw-card"><div className="hw-card-heading"><CheckCircle2 size={18}/><h2>结论、证据和下一步</h2></div>{review.clarifications.map(v=><p className="hw-note" key={v}>{v}</p>)}{review.checks.map(c=><article className="hw-check" key={c.id}><div><strong>{c.from_ref} → {c.to_ref} · {c.name}</strong><Tag status={c.status}/></div><p>{c.reason}</p><div className="hw-source-row">{c.evidence.map((s,i)=><span key={i}>{labels[s.field]||s.field}：<Source url={s.source_url||''}/></span>)}</div></article>)}<h3>优先验证任务</h3>{review.verification_actions.length?review.verification_actions.map((a,i)=><details className="hw-action" key={i}><summary><span>{a.priority}</span>{a.title}</summary><p>{a.reason}</p><ol>{a.steps.map(s=><li key={s}>{s}</li>)}</ol><p>通过条件：{a.pass_condition}</p><small>建议任务，尚未执行。</small></details>):<p className="hw-small">未产生具体连接任务；请确认已录入完整BOM和连接。</p>}</section>{review.change_impact.length>0&&<section className="hw-card"><div className="hw-card-heading"><Network size={18}/><h2>变更影响传播</h2></div>{review.change_impact.map((c,i)=><article className="hw-change" key={i}><strong>{c.ref} · {c.field==='part_id'?'更换器件':c.field==='quantity'?'数量变化':c.field.startsWith('parameter:')?'参数变化':'报价/连接/清单变化'}</strong><p>{show(c.before)} → {show(c.after)}</p><small>{c.effect} · 影响{c.affected_checks.length}项相邻检查</small></article>)}</section>}</>}
      </>}
      {tab==='parts'&&<><div className="hw-section-title"><div><h1>找到器件，也查清条件。</h1><p>本地参考库与自定义器件可加入方案；全网发现、工程经验与商家价格统一使用元宝搜索。</p></div><label className="hw-mode">联网模式<select value={mode} onChange={e=>setMode(e.target.value)}><option value="live">元宝真实搜索</option><option value="mock">MOCK测试 · 不联网</option></select></label></div><section className="hw-card"><div className="hw-card-heading"><Search size={18}/><h2>器件发现</h2><span>参考库{catalog.length}款 · 支持任意自定义型号</span></div><label className="hw-field-label" htmlFor="part-query">精确型号或所需功能</label><form className="hw-search-bar" onSubmit={e=>{e.preventDefault();searchParts();}}><input id="part-query" aria-label="器件型号或需求" value={query} onChange={e=>setQuery(e.target.value)} placeholder="输入精确型号或功能，例如 BME280 温湿度模块"/><select aria-label="筛选类别" value={category} onChange={e=>setCategory(e.target.value)}><option value="">全部类别</option>{Array.from(new Set(allParts.map(p=>p.category))).map(c=><option key={c} value={c}>{labels[c]||c}</option>)}</select><button type="submit" className="hw-primary" disabled={!!busy||partBusy||query.trim().length<2}>{partBusy?<><LoaderCircle size={15} className="spin"/>搜索中</>:'用元宝找器件'}</button></form><DiscoveryResults value={partResult} query={partSubmitted||query} busy={partBusy} error={partError} onAdd={addDiscovered} hasPart={hasDiscovered} onQuote={name=>{setPriceModel(name);setPriceType('芯片 模块');revealPrices();searchPrices(name,'芯片 模块');}} onInspect={(name,url)=>{setCustom({...custom,name,source_url:url,value:''});requestAnimationFrame(()=>document.getElementById('custom-part-name')?.focus());}}/><h3 className="hw-local-title">本机已收录器件 · 当前匹配{localParts.length}款</h3>{query&&!localParts.length&&<p className="hw-discovery-hint">本机库没有匹配型号，不影响上方联网查找与录入。</p>}<div className="hw-part-grid">{localParts.map(p=><article className="hw-part" key={p.id}><div><span>{labels[p.category]||p.category} · {labels[p.kind]||p.kind}</span><label><input type="checkbox" checked={comparisonIds.includes(p.id)} onChange={e=>setComparisonIds(e.target.checked?[...comparisonIds,p.id].slice(-8):comparisonIds.filter(id=>id!==p.id))}/>对比</label></div><h3>{p.name}</h3><p>{p.manufacturer}</p><dl>{Object.entries(p.facts).slice(0,4).map(([key,value])=><div key={key}><dt>{labels[key]||key}</dt><dd>{show(value.value)} {value.unit}</dd></div>)}</dl><p className="hw-small">{p.notes[0]}</p><Source url={p.source_url}/><div className="hw-part-actions"><button onClick={()=>addPart(p)}><Plus size={14}/>加入BOM</button><button onClick={()=>{setPriceModel(p.mpn);setPriceType(labels[p.kind]||p.kind);revealPrices();searchPrices(p.mpn,labels[p.kind]||p.kind);}}>查价格</button></div></article>)}</div><details className="hw-custom" open={custom.name?true:undefined}><summary>录入未收录型号与参数</summary><div className="hw-project-form"><label>精确型号<input id="custom-part-name" value={custom.name} onChange={e=>setCustom({...custom,name:e.target.value})}/></label><label>类别<input value={custom.category} onChange={e=>setCustom({...custom,category:e.target.value})}/></label><label>形态<select value={custom.kind} onChange={e=>setCustom({...custom,kind:e.target.value})}><option value="module">模块</option><option value="ic">芯片</option><option value="board">开发板</option><option value="mechanical">机械件</option></select></label><label>原始资料URL<input value={custom.source_url} onChange={e=>setCustom({...custom,source_url:e.target.value})}/></label><label>参数字段（可自定义）<input value={custom.key} onChange={e=>setCustom({...custom,key:e.target.value})}/></label><label>参数值<input type="text" value={custom.value} onChange={e=>setCustom({...custom,value:e.target.value})}/></label><label>单位<input value={custom.unit} onChange={e=>setCustom({...custom,unit:e.target.value})}/></label><button className="hw-button" onClick={addCustom}>保存型号 / 追加参数</button></div><p className="hw-small">相同型号再次保存可追加或修改参数；interfaces可填I2C,SPI。自定义事实标记为用户输入，不会因填了来源就自动核验。</p></details><button className="hw-button" disabled={comparisonIds.length<2||!!busy} onClick={()=>task('对比参数',async()=>setComparison(await api('compare',{project,part_ids:comparisonIds})))}>对比{comparisonIds.length}款 / 评估替代</button>{comparison&&<div className="hw-comparison"><p className="hw-note">{comparison.note}</p><div className="hw-table-scroll"><table><thead><tr><th>参数</th>{comparison.parts.map(p=><th key={p.id}>{p.name}</th>)}</tr></thead><tbody>{comparison.rows.map(r=><tr key={r.field} className={r.different?'different':''}><th>{labels[r.field]||r.field}{r.different?' · 差异':''}</th>{r.values.map((v,i)=><td key={i}>{show(v.value)} {v.unit}<small>{v.status==='source_checked'?'有原文依据':v.status==='user_asserted'?'用户输入':'证据不足'}</small></td>)}</tr>)}</tbody></table></div></div>}</section>
      <section className="hw-card"><div className="hw-card-heading"><Search size={18}/><h2>商家价格线索</h2><span>淘宝 / 立创 / 京东等</span></div><label className="hw-field-label" htmlFor="price-query">查找商品与报价</label><div className="hw-search-bar"><input id="price-query" aria-label="报价型号" value={priceModel} onChange={e=>setPriceModel(e.target.value)} placeholder="精确MPN / 模块型号"/><input aria-label="报价形态" value={priceType} onChange={e=>setPriceType(e.target.value)} placeholder="裸芯片 / 模块 / 套装"/><button className="hw-primary" disabled={!!busy||priceModel.length<2} onClick={()=>searchPrices()}>{busy==='元宝正在检索商家报价'?<><LoaderCircle size={15} className="spin"/>正在查报价</>:'元宝检索报价'}</button></div>{busy==='元宝正在检索商家报价'&&<div className="hw-discovery-state" role="status"><LoaderCircle size={16} className="spin"/><div><strong>正在查找“{priceModel}”的实际商品报价</strong><p>会区分缺价、起售价和多个SKU；结果直接显示在本区域。</p></div></div>}{priceError&&<p className="hw-model-error" role="alert">{priceError}</p>}<p className="hw-small">起售价、多SKU、阶梯价和不同币种不直接变成整套报价；确认页面规格后再录入BOM。</p><label className="hw-price-target">参考价填入哪一行？<select value={targetRef} onChange={e=>setTargetRef(e.target.value)}><option value="">选择BOM位号</option>{project.bom.map(b=><option key={b.ref} value={b.ref}>{b.ref} · {allParts.find(p=>p.id===b.part_id)?.name}</option>)}</select></label><SearchProof value={search}/><div className="hw-price-grid">{prices.map((p,i)=><article key={i}><span className="hw-tag unknown">待核对SKU / 套装</span><h3>{p.title}</h3><strong className="hw-price">{p.amount_cny===null?(p.product_url?'打开商品页查看价格':'未定位明确人民币报价'):`¥${p.amount_cny}`}</strong><small>{p.quote_type==='starting_price'?'起售价':p.quote_type==='multiple_skus_or_tiers'?'多个SKU或数量梯度':'搜索摘要线索'} · {new Date(p.retrieved_at).toLocaleDateString('zh-CN')}</small>{p.model_match_scope==='target_may_be_a_component_of_this_product'&&<p className="hw-note">目标型号可能只是这个组合模块中的器件，需核对实际SKU。</p>}<p>{p.snippet.slice(0,260)}</p><Source url={p.product_url||p.source_url} label={p.product_url?`打开${p.platform||"平台"}商品详情`:"查看参考来源 · 未确认商品页"}/><button className="hw-button" disabled={p.amount_cny===null||!targetRef} onClick={()=>applyPrice(p)}>预填参考价 · 待确认</button></article>)}</div>{hits.length>0&&<details className="hw-search-hits"><summary>元宝返回来源 · {hits.length}条</summary>{hits.map((h,i)=><article key={h.id+'-'+i}><h3>{h.title}</h3><p>{h.snippet.slice(0,350)}</p><Source url={h.product_url||h.url} label={h.product_url?`打开${h.platform||"平台"}商品详情`:"查看原始来源"}/></article>)}</details>}</section></>}
      {tab==='documents'&&<><div className="hw-section-title"><div><h1>问资料，答案带回原文。</h1><p>上传的文本/PDF在本机提取；全网补查仍走元宝搜索。缺少可引用内容时明确保留未知。</p></div></div><div className="hw-doc-grid"><section className="hw-card"><div className="hw-card-heading"><BookOpen size={18}/><h2>导入资料</h2></div><label>资料名称<input value={docName} onChange={e=>setDocName(e.target.value)} placeholder="精确型号、版本或文档名"/></label><label>原始链接（可选）<input value={docUrl} onChange={e=>setDocUrl(e.target.value)}/></label><label>粘贴原文<textarea rows={7} value={docText} onChange={e=>setDocText(e.target.value)} placeholder="粘贴手册或工程记录原句；保留单位和适用条件。"/></label><button className="hw-primary" disabled={!!busy||docText.length<10} onClick={addDocument}>导入文本</button><label className="hw-file-label">或上传PDF（文本型、≤10MB/60页）<input type="file" accept="application/pdf,.pdf" disabled={!!busy} onChange={e=>e.target.files?.[0]&&addPdf(e.target.files[0])}/></label><h3>选择问答资料</h3>{docs.map(d=><label className="hw-checkbox" key={d.id}><input type="checkbox" checked={docIds.includes(d.id)} onChange={e=>setDocIds(e.target.checked?[...docIds,d.id]:docIds.filter(id=>id!==d.id))}/>{d.name} · {d.page_count}页</label>)}<p className="hw-small">上传资料不自动变成厂商已核实规格；也不发送到元宝。查询会同时参考BOM中已收录的参数出处。</p></section><section className="hw-card"><div className="hw-card-heading"><MessageSquare size={18}/><h2>引用式问答</h2></div><label className="hw-field-label" htmlFor="document-question">你想从资料中确认什么？</label><textarea id="document-question" aria-label="资料问题" rows={4} value={question} onChange={e=>setQuestion(e.target.value)} placeholder="例如：VDD供电电压范围是多少？当前资料是否说明I2C？"/><button className="hw-primary" disabled={!!busy||question.length<2} onClick={ask}>按原文定位答案</button><button className="hw-button" onClick={()=>{setQuery(question);setTab('parts');}}>用元宝补查这个问题</button>{answer&&<div className="hw-answer"><h3>资料中的依据</h3><p className="hw-answer-text">{answer.answer}</p>{answer.citations.map((c,i)=><article key={i}><strong>[{i+1}] {c.document}{c.page?` · 第${c.page}页`:''}</strong><blockquote>{c.text}</blockquote><Source url={c.source_url}/></article>)}<p className="hw-small">{answer.scope}</p></div>}</section></div></>}
      {tab==='audit'&&<EvidenceAudit ready={!!health?.search_configured&&!!health?.decision?.configured} onConfigure={()=>setModelPanel(true)}/>}</fieldset>
      {tab!=='audit'&&<footer className="hw-footer"><span>RaceChip AI · 从需求到可复核的硬件工程交接</span><span>原生原理图 / PCB / EDA深度集成列下一阶段</span></footer>}
    </main></div>
  </div>;
}

